73	/**
74	 * Sanitizes tool arguments by recursively redacting sensitive fields.
75	 * Supports nested objects and arrays.
76	 */
77	function sanitizeToolArgs(args: unknown): unknown {
78	  if (typeof args === 'string') {
79	    return sanitizeErrorMessage(args);
80	  }
81	  if (typeof args !== 'object' || args === null) {
82	    return args;
83	  }
84	
85	  if (Array.isArray(args)) {
86	    return args.map(sanitizeToolArgs);
87	  }
88	
89	  const sanitized: Record<string, unknown> = {};
90	
91	  for (const [key, value] of Object.entries(args)) {
92	    // Decode key to handle URL-encoded sensitive keys (e.g., api%5fkey)
93	    let decodedKey = key;
94	    try {
95	      decodedKey = decodeURIComponent(key);
96	    } catch {
97	      // Ignore decoding errors
98	    }
99	    const keyNormalized = decodedKey.toLowerCase().replace(/[-_]/g, '');
100	    const isSensitive = SENSITIVE_KEY_PATTERNS.some((pattern) =>
101	      keyNormalized.includes(pattern.replace(/[-_]/g, '')),
102	    );
103	    if (isSensitive) {
104	      sanitized[key] = '[REDACTED]';
105	    } else {
106	      sanitized[key] = sanitizeToolArgs(value);
107	    }
108	  }
109	
110	  return sanitized;
111	}
