113	/**
114	 * Sanitizes error messages by redacting potential sensitive data patterns.
115	 * Uses [^\s'"]+ to catch JWTs, tokens with dots/slashes, and other complex values.
116	 */
117	function sanitizeErrorMessage(message: string): string {
118	  if (!message) return message;
119	
120	  let sanitized = message;
121	
122	  // 1. Redact inline PEM content
123	  sanitized = sanitized.replace(
124	    /-----BEGIN\s+[\w\s]+-----[\s\S]*?-----END\s+[\w\s]+-----/g,
125	    '[REDACTED_PEM]',
126	  );
127	
128	  const unquotedValue = `[^\\s]+(?:\\s+(?![a-zA-Z0-9_.-]+(?:=|:))[^\\s=:<>]+)*`;
129	  const valuePattern = `(?:"[^"]*"|'[^']*'|${unquotedValue})`;
130	
131	  // 2. Handle key-value pairs with delimiters (=, :, space, CLI-style --flag)
132	  const urlSafeKeyPatternStr = SENSITIVE_KEY_PATTERNS.map((p) =>
133	    p.replace(/[-_]/g, '(?:[-_]|%2D|%5F|%2d|%5f)?'),
134	  ).join('|');
135	
136	  const keyWithDelimiter = new RegExp(
137	    `((?:--)?("|')?(${urlSafeKeyPatternStr})\\2\\s*(?:[:=]|%3A|%3D)\\s*)${valuePattern}`,
138	    'gi',
139	  );
140	  sanitized = sanitized.replace(keyWithDelimiter, '$1[REDACTED]');
141	
142	  // 3. Handle space-separated sensitive keywords (e.g. "password mypass", "--api-key secret")
143	  const tokenValuePattern = `[A-Za-z0-9._\\-/+=]{8,}`;
144	  const spaceKeywords = [
145	    ...SENSITIVE_KEY_PATTERNS.map((p) =>
146	      p.replace(/[-_]/g, '(?:[-_]|%2D|%5F|%2d|%5f)?'),
147	    ),
148	    'bearer',
149	  ];
150	  const spaceSeparated = new RegExp(
151	    `\\b((?:--)?(?:${spaceKeywords.join('|')})(?:\\s*:\\s*bearer)?\\s+)(${tokenValuePattern})`,
152	    'gi',
153	  );
154	  sanitized = sanitized.replace(spaceSeparated, '$1[REDACTED]');
155	
156	  // 4. Handle file path redaction
157	  sanitized = sanitized.replace(
158	    /((?:[/\\][a-zA-Z0-9_-]+)*[/\\][a-zA-Z0-9_-]*\.(?:key|pem|p12|pfx))/gi,
159	    '/path/to/[REDACTED].key',
160	  );
161	
162	  return sanitized;
163	}
